	call_if_exists(enemy, "_on_path_timer_timeout", [])
	var state_after = get_prop(enemy, "current_state", -1)
	check("state_return", int(state_after) == 2, "Quando scatta il timer e il nemico perde di vista il giocatore, deve passare allo stato RETURN (2)")

